BEGIN TRANSACTION;

IF OBJECT_ID(N'dbo.mapping_role_user', N'U') IS NULL
BEGIN
  CREATE TABLE [dbo].[mapping_role_user] (
    [id] UNIQUEIDENTIFIER NOT NULL,
    [userid] VARCHAR(50) NULL,
    [role_id] UNIQUEIDENTIFIER NULL,
    [is_active] BIT NULL,
    [is_deleted] BIT NULL,
    [created_by] VARCHAR(100) NULL,
    [created_date] DATETIME NULL,
    [updated_by] VARCHAR(100) NULL,
    [updated_date] DATETIME NULL
    ,CONSTRAINT [PK_mapping_role_user] PRIMARY KEY ([id])
  );
END;

DELETE FROM [mapping_role_user];


COMMIT;
